CREATE SCHEMA IF NOT EXISTS private;

REVOKE ALL ON SCHEMA private FROM PUBLIC;

CREATE TABLE private.admin_users (user_id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION private.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS(SELECT 1 FROM private.admin_users WHERE user_id = nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub') $$;

CREATE TABLE "private"."nails_booking_limits" (
"id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
"ip" inet NOT NULL,
"phone" text NOT NULL,
"recorded_at" timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE "private"."nails_notification_outbox" (
"booking_id" text NOT NULL,
"receipt_hash" text NOT NULL,
"status" text DEFAULT 'pending'::text NOT NULL,
"claimed_at" timestamp with time zone,
"completed_at" timestamp with time zone,
"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "private"."nails_service_quotas" (
"scope" text NOT NULL,
"subject" text NOT NULL,
"window_start" timestamp with time zone NOT NULL,
"used" integer NOT NULL
);

CREATE TABLE "public"."ai_color_catalog" (
"id" uuid DEFAULT gen_random_uuid() NOT NULL,
"name" text NOT NULL,
"hex" text NOT NULL,
"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "public"."booking_payments" (
"id" uuid DEFAULT gen_random_uuid() NOT NULL,
"booking_id" text NOT NULL,
"amount" numeric NOT NULL,
"kind" text NOT NULL,
"method" text NOT NULL,
"paid_on" date DEFAULT ((now() AT TIME ZONE 'America/Sao_Paulo'::text))::date NOT NULL,
"note" text DEFAULT ''::text NOT NULL,
"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "public"."booking_slots" (
"booking_id" text NOT NULL,
"date" text NOT NULL,
"time" text NOT NULL,
"duration_minutes" integer NOT NULL
);

CREATE TABLE "public"."bookings" (
"id" text NOT NULL,
"service_id" text NOT NULL,
"service_name" text NOT NULL,
"price" numeric NOT NULL,
"date" text NOT NULL,
"time" text NOT NULL,
"client_name" text NOT NULL,
"client_phone" text NOT NULL,
"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
"notification_receipt" uuid,
"status" text DEFAULT 'scheduled'::text NOT NULL,
"cancellation_reason" text DEFAULT ''::text NOT NULL,
"client_notes" text DEFAULT ''::text NOT NULL,
"paid_amount" numeric DEFAULT 0 NOT NULL,
"client_phone_key" text GENERATED ALWAYS AS (
CASE
    WHEN ((length(regexp_replace(client_phone, '[^0-9]'::text, ''::text, 'g'::text)) = ANY (ARRAY[12, 13])) AND ("left"(regexp_replace(client_phone, '[^0-9]'::text, ''::text, 'g'::text), 2) = '55'::text)) THEN SUBSTRING(regexp_replace(client_phone, '[^0-9]'::text, ''::text, 'g'::text) FROM 3)
    ELSE regexp_replace(client_phone, '[^0-9]'::text, ''::text, 'g'::text)
END) STORED
);

CREATE TABLE "public"."schedule_blocks" (
"id" uuid DEFAULT gen_random_uuid() NOT NULL,
"date" text NOT NULL,
"start_time" text NOT NULL,
"end_time" text NOT NULL
);

CREATE TABLE "public"."services" (
"id" text NOT NULL,
"name" text NOT NULL,
"price" numeric NOT NULL,
"duration" text NOT NULL,
"image" text NOT NULL,
"created_at" timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
"description" text DEFAULT ''::text NOT NULL
);

ALTER TABLE "public"."services" ADD CONSTRAINT "services_pkey" PRIMARY KEY (id);

ALTER TABLE "private"."nails_booking_limits" ADD CONSTRAINT "nails_booking_limits_pkey" PRIMARY KEY (id);

ALTER TABLE "private"."nails_service_quotas" ADD CONSTRAINT "nails_service_quotas_pkey" PRIMARY KEY (scope, subject, window_start);

ALTER TABLE "private"."nails_service_quotas" ADD CONSTRAINT "nails_service_quotas_used_check" CHECK ((used >= 0));

ALTER TABLE "public"."booking_slots" ADD CONSTRAINT "booking_slots_duration_minutes_check" CHECK (((duration_minutes >= 1) AND (duration_minutes <= 720)));

ALTER TABLE "public"."booking_slots" ADD CONSTRAINT "booking_slots_pkey" PRIMARY KEY (booking_id);

ALTER TABLE "public"."ai_color_catalog" ADD CONSTRAINT "ai_color_catalog_hex_check" CHECK ((hex ~ '^#[0-9A-Fa-f]{6}$'::text));

ALTER TABLE "public"."ai_color_catalog" ADD CONSTRAINT "ai_color_catalog_hex_key" UNIQUE (hex);

ALTER TABLE "public"."ai_color_catalog" ADD CONSTRAINT "ai_color_catalog_name_key" UNIQUE (name);

ALTER TABLE "public"."ai_color_catalog" ADD CONSTRAINT "ai_color_catalog_pkey" PRIMARY KEY (id);

ALTER TABLE "private"."nails_notification_outbox" ADD CONSTRAINT "nails_notification_outbox_pkey" PRIMARY KEY (booking_id);

ALTER TABLE "private"."nails_notification_outbox" ADD CONSTRAINT "nails_notification_outbox_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'uncertain'::text])));

ALTER TABLE "public"."schedule_blocks" ADD CONSTRAINT "schedule_blocks_check" CHECK ((start_time < end_time));

ALTER TABLE "public"."schedule_blocks" ADD CONSTRAINT "schedule_blocks_date_check" CHECK ((date ~ '^\d{4}-\d{2}-\d{2}$'::text));

ALTER TABLE "public"."schedule_blocks" ADD CONSTRAINT "schedule_blocks_end_time_check" CHECK ((end_time ~ '^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'::text));

ALTER TABLE "public"."schedule_blocks" ADD CONSTRAINT "schedule_blocks_pkey" PRIMARY KEY (id);

ALTER TABLE "public"."schedule_blocks" ADD CONSTRAINT "schedule_blocks_start_time_check" CHECK ((start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'::text));

ALTER TABLE "public"."bookings" ADD CONSTRAINT "bookings_cancellation_reason_check" CHECK ((length(cancellation_reason) <= 1000));

ALTER TABLE "public"."bookings" ADD CONSTRAINT "bookings_client_notes_check" CHECK ((length(client_notes) <= 3000));

ALTER TABLE "public"."bookings" ADD CONSTRAINT "bookings_paid_amount_check" CHECK ((paid_amount >= (0)::numeric));

ALTER TABLE "public"."bookings" ADD CONSTRAINT "bookings_pkey" PRIMARY KEY (id);

ALTER TABLE "public"."bookings" ADD CONSTRAINT "bookings_status_check" CHECK ((status = ANY (ARRAY['scheduled'::text, 'confirmed'::text, 'completed'::text, 'cancelled'::text, 'no_show'::text])));

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_amount_check" CHECK ((amount > (0)::numeric));

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_kind_check" CHECK ((kind = ANY (ARRAY['deposit'::text, 'payment'::text, 'refund'::text])));

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_method_check" CHECK ((method = ANY (ARRAY['pix'::text, 'cash'::text, 'debit'::text, 'credit'::text, 'transfer'::text, 'other'::text])));

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_note_check" CHECK ((length(note) <= 500));

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_pkey" PRIMARY KEY (id);

ALTER TABLE "public"."booking_slots" ADD CONSTRAINT "booking_slots_booking_id_fkey" FOREIGN KEY (booking_id) REFERENCES bookings(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "private"."nails_notification_outbox" ADD CONSTRAINT "nails_notification_outbox_booking_id_fkey" FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE CASCADE;

ALTER TABLE "public"."booking_payments" ADD CONSTRAINT "booking_payments_booking_id_fkey" FOREIGN KEY (booking_id) REFERENCES bookings(id) ON DELETE RESTRICT;
